from pathlib import Path
import ast,json,html,textwrap
out=Path('docs/accounting-implementation')
old=Path('docs/akaunting/build-guide.py').read_text(encoding='utf-8')
exec(old[old.index('def table('):old.index('feature=tree(')])
sources=[('Frappe architecture','https://docs.frappe.io/framework/user/en/basics/architecture'),('Frappe REST API','https://docs.frappe.io/framework/user/en/api/rest'),('ERPNext license','https://raw.githubusercontent.com/frappe/erpnext/develop/license.txt'),('Accounting entries','https://docs.frappe.io/erpnext/accounting-entries'),('Immutable ledger','https://docs.frappe.io/erpnext/immutable-ledger-in-erpnext'),('Chart of accounts','https://docs.frappe.io/erpnext/chart-of-accounts'),('Payment entry','https://docs.frappe.io/erpnext/payment-entry'),('Accounting reports','https://docs.frappe.io/erpnext/accounting-reports')]
steps=[
('Agree the scope and ownership', ['Business needs','Accountant input','Reference workflows'], ['Define release one','List later modules','Choose native or API'], ['Approved scope','Acceptance examples','Named owners'], 'Agree scope before any accounting coding.',
['Inventory the required screens, reports, document fields and business rules. Use ERPNext as the functional reference, with a pinned release for comparison.','Name a finance owner to approve account mappings, opening balances, taxes and worked examples. PM owns scope; engineering owns implementation.','Define release one as single-currency service accounting: accounts, invoices, bills, payments, journals and essential reports. Do not label this complete ERPNext parity.'],
'Output: a signed scope and feature matrix with Required / Later / Not applicable decisions.',
'Example: decide whether cheque tracking is only a reference field or a full issued-to-cleared lifecycle.'),
('Add Accounting to the shared product system',['Existing Judibas login','Users and companies','Shared invitations'],['Register product','Assign access and roles','Protect every endpoint'],['Accounting workspace','Assigned users only','Company isolation'],'An unassigned user must fail both UI and API access.',
['Register an Accounting product using the same catalogue, application switcher, shared login and access-assignment pattern as other Judibas products.','Keep account creation, invitations and company creation in Administration. Show accounting configuration and transactions inside the Accounting workspace.','Define separate abilities for view, create, submit, pay, journal, cancel, export and period management. Enforce company access on every server action, not only in Vue.'],
'Output: a working empty product shell with permission checks and role tests.',
'Example: a cashier can record authorized payments without acquiring journal-adjustment or cancellation powers.'),
('Create the accounting data foundation',['One PostgreSQL DB','Company identifiers','Agreed account tree'],['Add prefixed tables','Use decimal amounts','Enforce constraints'],['Accounts and periods','Voucher headers/lines','Ledger and allocations'],'Reject cross-company references and invalid money values.',
['Keep the existing shared PostgreSQL database. Add accounting-specific tables and indexes rather than changing unrelated product records.','Model periods, accounts, parties, vouchers, journal lines, invoice items, payment allocations, audit and posting requests. Proposed table names are design choices, not ERPNext table copies.','Use fixed-precision decimal arithmetic with an agreed rounding policy. Enforce company-consistent references, unique document numbers and idempotency keys; store currency codes explicitly.'],
'Output: reviewed migrations, relationships, constraints and a data dictionary.',
'Example: one voucher header belongs to company A; every posting account and invoice allocation must also belong to company A.'),
('Build and prove the ledger engine',['Validated voucher','Account mapping','Posting request key'],['Check balanced lines','Lock and post atomically','Block duplicate posting'],['Posted voucher','Balanced ledger','Traceable source link'],'A failure must leave neither half a posting nor a duplicate.',
['Create one server-side posting service shared by invoices, payments and journals. Check permissions, company, accounts, period, currency and balanced totals before posting.','Lock the relevant records and commit the voucher state, ledger lines and audit trail within one database transaction. Retried requests must return or identify the prior result.','Keep financial posting synchronous and atomic. Queue notifications and broadcasts only after commit; a failed broadcast must not make a successful financial posting look failed.'],
'Output: a tested posting engine before building the transaction screens.',
'Example: two simultaneous Submit clicks must result in one posted invoice and one set of ledger lines.'),
('Configure accounts and opening balances',['Approved trial balance','Migration cutoff date','Customer/supplier dues'],['Create account groups','Map posting accounts','Import opening balances'],['Company account tree','Reconciled opening data','Verified defaults'],'Opening totals must tie to the approved source records.',
['Build account-tree management with group versus posting accounts. Add company defaults, fiscal periods, currency and controlled document-number sequences.','Prepare customer/supplier records and bank/cash accounts. Reuse shared contacts only when their identity and company meaning match; do not silently merge unrelated parties.','Load opening ledger balances and invoice-level outstanding amounts through a deliberate migration process. Reconcile them together so opening receivables/payables are not counted twice.'],
'Output: a finance-approved opening balance pack and master-data checklist.',
'Example: the customer-control account total must agree with the imported customer outstanding detail.'),
('Build sales invoices and customer balances',['Customer and items','Rates and terms','Income/tax mappings'],['Calculate on server','Save draft or submit','Create receivable posting'],['Invoice and print view','Customer outstanding','Income ledger lines'],'Invoice totals, ledger totals and outstanding amounts agree.',
['Implement a Judibas-style invoice list, form, preview and print/PDF view. Clearly distinguish a draft, a posted invoice and its payment state.','Recalculate quantities, rates, discounts, taxes and rounding on the server. Snapshot the posted document details required for historical reporting.','Post receivables, income and applicable tax lines through the ledger service. Keep payment allocation separate; include controlled credit/return handling in the agreed release scope.'],
'Output: draft-to-posted invoicing with correct customer balances and printable documents.',
'Example: a Rs 100,000 service invoice creates Rs 100,000 receivable; cash remains unchanged until payment.'),
('Build purchases and supplier obligations',['Supplier bill','Expense/asset mapping','Supplier reference'],['Check duplicate bill','Calculate and submit','Create payable posting'],['Purchase invoice','Supplier outstanding','Expense/asset lines'],'Recording a bill must not also record a payment by accident.',
['Implement supplier bills using the same draft, review, submit and historical-preview pattern. Retain supplier references, dates, attachments and source evidence.','Post expense or asset and payable lines through the same ledger engine. Add duplicate supplier-reference checks and clear due-date information.','Begin with service bills. Stock receipts, stock valuation and inventory cost postings require a separately tested extension; do not imitate them with generic expense entries.'],
'Output: supplier bills and accurate payable detail with supporting evidence.',
'Example: a Rs 30,000 unpaid service bill increases expense and payables; the bank balance does not move.'),
('Build payments, allocations and reconciliation',['Bank/cash account','Receipt or payment','Open invoice amounts'],['Receive, Pay, Transfer','Allocate without overpay','Match bank statement'],['Settled/outstanding dues','Allocation audit trail','Reconciled bank view'],'Concurrent allocations cannot exceed the remaining balance.',
['Implement customer receipts, supplier payments and internal transfers. Add advances and unallocated amounts only with explicit later-allocation rules.','Lock invoices and allocation records during settlement. Define policies for refunds, small differences, fees, overpayments and reversals.','Provide CSV/manual bank-statement import and reconciliation first. Add provider connectivity only after availability is verified. Keep invoice allocation and bank reconciliation as separate operations.'],
'Output: full/partial settlement, internal transfers and a bank reconciliation workflow.',
'Example: receive Rs 60,000 against a Rs 100,000 invoice; outstanding becomes Rs 40,000 without adding new revenue.'),
('Add journals, corrections and period control',['Adjustment explanation','Supporting evidence','Authorized accountant'],['Validate balanced journal','Reverse, do not overwrite','Respect closed periods'],['Journal and reversal','Original source retained','Controlled correction'],'Posted history cannot be silently changed through normal APIs.',
['Implement balanced manual journals for approved adjustments with evidence and clear account/party selections. Require specific journal permissions.','Implement reversal-linked correction rather than direct editing of posted amounts. Decide how related allocations, credits and dependent documents are reversed or blocked.','Close periods with authorized reopening controls. Audit submit, cancellation, correction and export events with actor, company, time and meaningful business descriptions.'],
'Output: traceable correction paths, period controls and understandable audit history.',
'Example: cancelling an incorrect invoice preserves the original posting and records an authorized opposite effect.'),
('Build reports and the Judibas user experience',['Posted ledger lines','Party allocations','Company/date filters'],['Aggregate consistently','Trace totals to vouchers','Queue large exports'],['GL, trial balance, P&L','Balance sheet, ageing','Clear loading feedback'],'Every summary can be explained by its underlying records.',
['Build General Ledger, Trial Balance, Balance Sheet, Profit and Loss, receivables/payables ageing and account/party statements. Validate cash-flow classification before releasing that report.','Keep totals based on the ledger and outstanding figures based on valid allocations. Apply the same company, date, permission and status filters to screens and exports.','Match Judibas navigation, themes, tables and dialogs. Use role-relevant dashboards, clickable totals, in-button loaders, pagination and readable previews. Broadcast permitted changes after commit using Reverb/Pusher.'],
'Output: reconciled financial reports and a responsive Accounting workspace.',
'Example: clicking an outstanding customer total opens the exact unpaid invoice detail visible to that user.'),
('Validate correctness and plan wider parity',['Finance test scenarios','Concurrent-user tests','Reference results'],['Test posting and scope','Reconcile every report','Approve deferred phases'],['Accepted release one','Documented gaps','Extension test plan'],'Finance signs off the results, not only the appearance.',
['Test rounding, partial payments, advances, retries, concurrent posting, credit notes, cancellation, period locks and unauthorized cross-company access. Use meaningful database and browser tests.','Compare representative examples against independently calculated expected results and a configured reference installation. Test backups, exports, worker failures and real-time access.','Track wider parity explicitly: multi-currency/FX, dimensions, budgets, finance books, stock/COGS, assets, payroll, tax localization and cheque lifecycle each need dedicated specifications and validation.'],
'Output: an acceptance pack, known limitations and an approved next-phase backlog.',
'Example: a failed notification must not duplicate a payment or persuade the operator to post it again.'),
('Pilot, migrate and release safely',['Accepted staging build','Signed opening figures','Backup and rollback plan'],['Pilot one company','Reconcile at cutoff','Monitor and expand'],['Controlled production','Recoverable data','Measured performance'],'Do not expand until pilot balances and operations agree.',
['Pilot with one company and a small finance team. Import a controlled opening dataset and run agreed scenarios before wider employee access.','Choose the financial source of truth at cutover. Avoid manual dual entry into two live ledgers without a controlled reconciliation process. Restore-test backups before launch.','Deploy supervised workers, scheduler and Reverb; monitor queries, locks, failed jobs, disk and response times. Load-test the agreed concurrency assumption rather than guaranteeing capacity from server specifications.'],
'Output: a reconciled pilot, go-live checklist, recovery runbook and support ownership.',
'Example: plan for 400 registered users, but measure actual simultaneous active users and expensive report workloads.')]
def diagram(i,s):
 title,ins,actions,outs,gate,*_=s
 parts=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 310" role="img" aria-label="Step '+str(i)+' implementation diagram"><rect width="700" height="310" rx="14" fill="#f5f6fb"/>',f'<text x="22" y="32" font-family="Arial" font-size="17" font-weight="bold" fill="#303850">STEP {i:02d} / {html.escape(title)}</text>']
 for x,label,lines,color in [(18,'START WITH',ins,'#168782'),(248,'BUILD / DECIDE',actions,'#6554cc'),(478,'DELIVER',outs,'#3974ba')]:
  parts.append(f'<rect x="{x}" y="57" width="204" height="152" rx="10" fill="white" stroke="{color}"/><text x="{x+14}" y="82" font-size="12" font-family="Arial" font-weight="bold" fill="{color}">{label}</text>')
  y=109
  for line in lines:
   for wrapped in textwrap.wrap(line,25):parts.append(f'<text x="{x+14}" y="{y}" font-size="12.5" font-family="Arial" fill="#303850">{html.escape(wrapped)}</text>');y+=16
   y+=5
 for x in [224,454]:parts.append(f'<path d="M{x} 129h20m-7-5 7 5-7 5" fill="none" stroke="#7c87a0" stroke-width="2"/>')
 parts.append('<rect x="18" y="227" width="664" height="66" rx="9" fill="#e9e6fa"/><text x="31" y="249" font-family="Arial" font-weight="bold" font-size="12" fill="#6554cc">PASS THIS CHECK BEFORE MOVING ON</text>')
 for j,line in enumerate(textwrap.wrap(gate,85)):parts.append(f'<text x="31" y="{269+j*15}" font-family="Arial" font-size="12.5" fill="#303850">{html.escape(line)}</text>')
 parts.append('</svg>');return ''.join(parts)
plan_tree=tree('Judibas Accounting implementation tree','JUDIBAS|Accounting plan',[
('Choose the route',['1. Scope and finance ownership','Native Laravel engine or ERPNext API','Licensing and version decisions']),('Use shared access',['2. Product registration and assignment','Existing users, invites and companies','Role and API company restrictions']),('Build the foundation',['3. Database and decimal model','4. Atomic ledger posting engine','5. Accounts and opening balances']),('Add transactions',['6. Sales and receivables','7. Purchases and payables','8. Payments and reconciliation']),('Protect and explain',['9. Journals, reversals and periods','10. Financial reports and Judibas UI','Permissioned live updates and exports']),('Prove correctness',['11. Finance and concurrency tests','Reconcile reports and source vouchers','Document later parity work']),('Release and grow',['12. Pilot, migrate and monitor','Keep one source of financial truth','Add FX, stock, HR/payroll in phases'])])
(out/'implementation-tree.svg').write_text(plan_tree,encoding='utf-8')
pages=[]
def page(title,body,kicker='JUDIBAS ACCOUNTING / IMPLEMENTATION ROADMAP'):pages.append(dict(title=title,body=body,kicker=kicker))
page('Accounting in Judibas','<div class="cover-title">From ERPNext workflows<br>to a Judibas product</div><p class="lead">A step-by-step implementation proposal for Laravel + Vue 3, with one master tree and twelve individual step diagrams.</p><div class="cover-tags">12 STEPS / 13 DIAGRAMS / DELIVERY CHECKPOINTS</div><div class="cover-bottom"><strong>Prepared for PM, engineering and finance review</strong><p>21 October 2026<br>Planning document; implementation has not started</p></div>'+box('Primary route: build a Judibas-native Accounting product using independently specified ERPNext-style workflows. The API integration route is explained separately. ERPNext Python modules cannot simply be pasted into the Laravel application.'),'PRODUCT IMPLEMENTATION PROPOSAL')
page('First decide what “copy” means','<p>Judibas currently uses Laravel 12, PHP, Vue 3 and a shared PostgreSQL database. ERPNext depends on the Frappe application framework. Similar-looking screens do not make the two application runtimes interchangeable. [1]</p>'+table(['Route','How it works','Main trade-off'],[['A. Native Judibas product','Implement accounting rules and UI in Laravel/Vue; keep the existing shared database.','One user experience, but Judibas must build and validate the accounting engine.'],['B. ERPNext integration','Run ERPNext separately; Judibas calls authorized APIs and maps business identities.','Reuses the engine, but adds separate operations, mapping and synchronization.']])+'<h3>Recommendation for your stated requirement</h3><p>Route A matches your existing product pattern and shared database preference. Select it only with an accountant involved and phased acceptance. If reducing custom ledger engineering is the priority, first prove Route B with a small integration pilot. Neither route is an automatic module copy.</p>'+box('ERPNext publishes a GPLv3 license. Before reusing its actual code, templates or assets, review the applicable license obligations for the intended distribution and deployment. API separation is an architectural choice, not a blanket licensing exemption. [3]')+'<p class="caption">All steps and database suggestions below are proposed Judibas implementation decisions, not claims that they already exist.</p>'+refs([1,2,3]))
page('Overall implementation tree','<p class="caption">Follow the numbered sequence. Ledger correctness is established before transaction screens and dashboards.</p><figure>'+plan_tree+'</figure>')
for i,s in enumerate(steps,1):
 title,ins,actions,outs,gate,tasks,output,example=s;svg=diagram(i,s);(out/'steps'/f'step-{i:02d}.svg').write_text(svg,encoding='utf-8')
 page(f'Step {i:02d} / {title}','<figure class="step-figure">'+svg+'</figure><h3>What we do</h3>'+bullets(tasks)+box('<strong>Completion checkpoint</strong><br>'+output)+'<p class="example"><strong>Example:</strong> '+example.removeprefix('Example: ')+'</p>','PROPOSED IMPLEMENTATION / STEP '+str(i)+' OF 12')
page('If we choose ERPNext integration','<p>This is a separate route from the twelve-step native plan. Frappe exposes REST APIs; the chosen ERPNext version and permitted document lifecycle must be tested before relying on them. [2]</p>'+table(['Sequence','Integration work required'],[['1. Deploy a reference service','Operate ERPNext with its own supported application runtime and database. Do not let Laravel write its internal tables directly.'],['2. Map identities and companies','Map Judibas users, company IDs, customers, suppliers and accounts to the ERPNext records. Shared sign-in requires deliberate identity integration.'],['3. Choose the financial source of truth','ERPNext owns authoritative ledger records. Judibas stores integration mappings and any explicitly identified cache.'],['4. Build a server-side adapter','Keep credentials on the server. Validate the actor and company; do not expose a powerful shared API token to the browser.'],['5. Support safe retries','Use request identifiers, remote references and reconciliation checks so a timeout does not create a duplicate document.'],['6. Test the full lifecycle','Create, submit, pay, reconcile, reverse and report. Include unavailable service, changed permissions and partial failure scenarios.']])+box('Prefer one authoritative ledger. Updating two financial databases independently and hoping they stay synchronized creates reconciliation risk. A “single database only” requirement is a strong reason to choose the native route instead.')+'<p class="caption">The adapter, sign-in and retry design above are recommendations, not out-of-the-box capabilities guaranteed by the REST API.</p>'+refs([2]))
page('Scope, dependencies and go-live decisions','<h3>Release in phases</h3>'+table(['Phase','Scope','Release condition'],[['1. Foundation','Steps 1-5: scope, access, schema, ledger, opening data','Posting invariants and company isolation pass.'],['2. Working accounting','Steps 6-10: documents, settlement, controls and reports','End-to-end finance examples reconcile.'],['3. Pilot and launch','Steps 11-12: tests, migration and monitored rollout','Finance and operational owners accept the pilot.'],['4. Broader parity','FX, budgets/dimensions, stock, assets, payroll, localization and cheque workflows','Each extension has its own acceptance scenarios.']])+'<h3>Decisions needed before development</h3>'+bullets(['Choose native Judibas or separate ERPNext integration.','Nominate the finance owner and agree release-one currency and business scope.','Approve document and payment approval/correction permissions.','Identify the opening-data source and migration cutoff.','Prioritize later modules and define their accounting handover points.'])+'<h3>Schedule and cost</h3><p>This is a substantial accounting project, not a short UI port. Estimate the delivery schedule only after the scope, team, accountant availability and integration route are agreed. Track progress by demonstrated financial acceptance, not by screen count.</p>')
page('Sources and document boundary','<p>Official sources checked on 21 October 2026. The proposed Laravel/PostgreSQL design and step diagrams are original recommendations for Judibas; they are not official Frappe migration instructions.</p><ol class="source-list">'+''.join('<li><strong>'+html.escape(t)+'</strong><br><a href="'+u+'">'+html.escape(u)+'</a></li>' for t,u in sources)+'</ol><h3>Related local reference</h3><p>Frappe-Accounting-Guide.pdf describes the product features. This implementation roadmap explains how to organize a Judibas project based on those requirements.</p>'+box('No production database, product access, financial table or deployment was changed while preparing this document. Code snippets, table concepts and workflows are planning material.'))
css=next(ast.literal_eval(n.value) for n in ast.parse(old).body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='css' for t in n.targets))
css+='h1{font-size:23pt}.cover-title{font-size:31pt}.cover-bottom{margin-top:55px}.step-figure svg{height:auto;width:100%;max-height:81mm}.example{font-size:10pt;color:#66738a}.page:has(.step-figure) li{margin-bottom:14px}.page:has(.step-figure) .note{margin-top:16px}.source-list{font-size:9pt}'
(out/'guide.css').write_text(css,encoding='utf-8');(out/'guide-content.json').write_text(json.dumps(pages,ensure_ascii=False),encoding='utf-8')
doc='<!doctype html><html><head><meta charset="utf-8"><title>Judibas Accounting Implementation Roadmap</title><style>'+css+'</style></head><body>'+''.join('<section class="page"><div class="topline"></div><div class="kicker">'+p['kicker']+'</div><h1>'+p['title']+'</h1>'+p['body']+'<div class="footer"><span>JUDIBAS / ACCOUNTING IMPLEMENTATION PLAN</span><span>'+str(i+1)+' / '+str(len(pages))+'</span></div></section>' for i,p in enumerate(pages))+'</body></html>'
(out/'Judibas-Accounting-Implementation.html').write_text(doc,encoding='utf-8');print('Prepared',len(pages),'pages, 12 step diagrams and 1 master tree')
